mapper.sql:
company_id = #{companyId}
AND temp_id = #{tempId}

  AND user_id IN

    #{uid}

mapper.select:
SELECT record_date FROM selfservice_user_daily_record WHERE
GROUP BY record_date ORDER BY record_date DESC
LIMIT #{offset}, #{limit}

SELECT r.* FROM selfservice_user_daily_record r INNER JOIN ( SELECT s.user_id, s.record_date, MAX(s.id) AS pick_id FROM selfservice_user_daily_record s INNER JOIN ( SELECT user_id, MAX(record_date) AS max_record_date FROM selfservice_user_daily_record WHERE
GROUP BY user_id ) m ON s.user_id = m.user_id AND s.record_date = m.max_record_date WHERE
GROUP BY s.user_id, s.record_date ) x ON r.user_id = x.user_id AND r.record_date = x.record_date AND r.id = x.pick_id ORDER BY r.record_date DESC LIMIT #{offset}, #{limit}
